CREATE TABLE operation_resource_reservations(id TEXT PRIMARY KEY,app_id TEXT NOT NULL,strategy_id TEXT NOT NULL,resource_id TEXT NOT NULL,resource_version INTEGER NOT NULL,start_minute INTEGER NOT NULL,end_minute INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0 AND quantity<=9007199254740991),state TEXT NOT NULL CHECK(state IN ('reserved','released')),created_at TEXT NOT NULL,CHECK(end_minute>start_minute));
CREATE INDEX operation_resource_active ON operation_resource_reservations(resource_id,state,start_minute,end_minute);
CREATE TABLE operation_strategy_actions(id TEXT PRIMARY KEY,app_id TEXT NOT NULL,strategy_id TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES operation_cases(id),proposal_id TEXT NOT NULL,action TEXT NOT NULL,input_hash TEXT NOT NULL,input_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(strategy_id,proposal_id));
